require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$items=loadCandidateRecords();$stages=['Applied','Screening','Interview','Offer','Rejected'];$activePage='pipeline';$pageTitle='Pipeline · ResumeIQ';$pageStyles='<style>.board{display:grid;grid-template-columns:repeat(5,minmax(230px,1fr));gap:9px;overflow-x:auto;margin-top:12px}.column{background:#f0f1f7;border:1px solid var(--line);border-radius:11px;padding:9px;min-height:520px}.column.over{outline:2px solid var(--primary)}.column-head{display:flex;justify-content:space-between;padding:5px 4px 11px;font-size:10px;font-weight:700}.card{display:block;background:#fff;border:1px solid var(--line);border-radius:9px;padding:11px;margin-bottom:7px;cursor:grab}.card strong{font-size:10px}.card p{font-size:8px;color:var(--muted);margin:4px 0 8px}.card-foot{display:flex;justify-content:space-between;font-size:8px;color:var(--muted);border-top:1px dashed var(--line);padding-top:7px}@media(max-width:850px){.board{grid-template-columns:repeat(5,250px)}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-table-columns"></i> Hiring workflow</div><h1>Candidate pipeline</h1><p><?=count($items)?> candidates · drag cards between stages; every move saves to MySQL.</p></div><a class="btn" href="wishlist.php"><i class="fa-solid fa-heart"></i>Wishlist & email</a></section><section class="board"><?php foreach($stages as $stage):$group=array_values(array_filter($items,fn($x)=>($x['stage']??'Applied')===$stage));?><article class="column" data-stage="<?=$stage?>"><div class="column-head"><span><?=$stage?></span><b class="count"><?=count($group)?></b></div><div class="drop"><?php foreach($group as $c):$d=candidatePresentation($c);?><a class="card" draggable="true" data-id="<?=htmlspecialchars($c['id'])?>" href="candidate_detail.php?id=<?=urlencode($c['id'])?>"><strong><?=htmlspecialchars($d['name'])?></strong><p><?=htmlspecialchars($d['role'])?></p><div class="card-foot"><span><?=(int)$c['score']?>% score</span><span><?=htmlspecialchars($c['source']??'Unknown')?></span></div></a><?php endforeach?></div></article><?php endforeach?></section><script>const token='<?=csrfToken()?>',cards=[...document.querySelectorAll('.card')],cols=[...document.querySelectorAll('.column')];let drag;cards.forEach(c=>{c.ondragstart=e=>{drag=c;c.classList.add('dragging')};c.ondragend=()=>c.classList.remove('dragging');c.onclick=e=>{if(c.classList.contains('dragging'))e.preventDefault()}});function counts(){cols.forEach(c=>c.querySelector('.count').textContent=c.querySelectorAll('.card').length)}cols.forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('over')};col.ondragleave=()=>col.classList.remove('over');col.ondrop=async e=>{e.preventDefault();col.classList.remove('over');const old=drag.parentElement;col.querySelector('.drop').appendChild(drag);counts();const r=await fetch('pipeline_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({id:drag.dataset.id,stage:col.dataset.stage,csrf:token})});if(!r.ok){old.appendChild(drag);counts();alert('Move could not be saved')}}});</script>
